package com.ecommerce.inventory.service; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.util.*; import org.springframework.http.*; @RestController @RequestMapping("/api/inventory") public class InventoryController { final InventoryRepository repo; InventoryController(InventoryRepository r){repo=r;} @GetMapping("/{productId}") public Inventory get(@PathVariable UUID productId){return repo.findByProductId(productId).orElseThrow(()->new NoSuchElementException("Inventory not found"));} record Req(@NotNull UUID productId,@Min(0) int quantity){} @PostMapping public ResponseEntity<Inventory> create(@RequestBody Req x){Inventory i=new Inventory();i.setProductId(x.productId());i.setAvailable(x.quantity());return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(i));} @PostMapping("/{productId}/reserve") public Inventory reserve(@PathVariable UUID productId,@RequestParam @Min(1) int quantity){Inventory i=get(productId); if(i.getAvailable()<quantity) throw new IllegalStateException("Insufficient inventory"); i.setAvailable(i.getAvailable()-quantity); return repo.save(i);} @PostMapping("/{productId}/release") public Inventory release(@PathVariable UUID productId,@RequestParam @Min(1) int quantity){Inventory i=get(productId);i.setAvailable(i.getAvailable()+quantity);return repo.save(i);} }